import * as T from 'three';
import {SegmentIndex} from './spatial.js';
import {heightAt} from './terrain-runtime.js';
import {project} from './model.js';
export function addAtmosphere(scene,data,baked){
 const {vegetation,lamps,heads,materials}=baked;scene.add(vegetation,lamps);
 const glow=materials.find(m=>m.userData.cityShader==='glow'),bulb=materials.find(m=>m.userData.cityShader==='bulb');
 // Only eight local lights affect shaded surfaces; their assignments fade smoothly.

 const labels=Array.from({length:8},()=>{const sprite=new T.Sprite(new T.SpriteMaterial({transparent:true,depthTest:false}));sprite.renderOrder=10;sprite.visible=false;scene.add(sprite);return sprite;});let labelLast=0;
 const pool=Array.from({length:8},()=>{const l=new T.PointLight('#ffd699',0,40,2);l.visible=false;scene.add(l);return l;});const headIndex=new SegmentIndex();for(const h of heads)headIndex.add({...h,a:[h.p[0],h.p[2]],b:[h.p[0],h.p[2]]});let dusk=false,last=0,previous=0;const slots=pool.map(l=>({l,current:null,target:null}));
 return {vegetation,lamps,treeCount:0,lampsCount:heads.length,setDusk(value){dusk=value;glow.uniforms.night.value=value?1:0;bulb.emissiveIntensity=value?3:.05;for(const l of pool){l.visible=value;if(!value)l.intensity=0;}for(const mesh of lamps.children)if(mesh.material===glow)mesh.visible=value;},update(now,pos){const dt=Math.min(.1,(now-previous)/1000);previous=now;for(const slot of slots){const desired=dusk&&slot.current&&slot.current===slot.target?100:0;slot.l.intensity+=(desired-slot.l.intensity)*(1-Math.exp(-dt*3));if(slot.current!==slot.target&&slot.l.intensity<1){slot.current=slot.target;if(slot.current){const h=slot.current;slot.l.position.set(h.p[0],6.5+(h.base??heightAt(h.p[0],h.p[2])),h.p[2]);}}}if(now-labelLast>900){labelLast=now;const streetLevel=pos.y-heightAt(pos.x,pos.z)<200;for(const mesh of lamps.children)mesh.visible=(mesh.material!==glow||dusk)&&(!streetLevel||mesh.boundingSphere.center.distanceTo(pos)<2000+mesh.boundingSphere.radius);for(const mesh of vegetation.children)if(mesh.userData.detail)mesh.visible=!streetLevel||mesh.boundingSphere.center.distanceTo(pos)<2000+mesh.boundingSphere.radius;const near=pos.y-heightAt(pos.x,pos.z)<150?data.pois.map(p=>({p,xz:project(p)})).map(p=>({...p,d:(p.xz[0]-pos.x)**2+(p.xz[1]-pos.z)**2})).filter(p=>p.d<90000).sort((a,b)=>a.d-b.d).slice(0,8):[];labels.forEach((sprite,i)=>{const n=near[i];sprite.visible=!!n;if(!n)return;if(sprite.userData.name!==n.p.name){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');ctx.font='600 26px sans-serif';canvas.width=Math.min(900,Math.ceil(ctx.measureText(n.p.name).width)+32);canvas.height=52;ctx.fillStyle='#132630';ctx.fillRect(0,0,canvas.width,52);ctx.fillStyle='#def0de';ctx.font='600 26px sans-serif';ctx.textBaseline='middle';ctx.fillText(n.p.name,16,26,canvas.width-32);sprite.material.map?.dispose();sprite.material.map=new T.CanvasTexture(canvas);sprite.material.needsUpdate=true;sprite.userData.name=n.p.name;sprite.scale.set(canvas.width/52*5,5,1);}sprite.position.set(n.xz[0],(n.p.height||18)+8+heightAt(...n.xz),n.xz[1]);});}if(!dusk||now-last<500)return;last=now;const near=headIndex.near(pos.x,pos.z,180).filter(h=>(h.p[0]-pos.x)**2+(h.p[2]-pos.z)**2<32400).sort((a,b)=>((a.p[0]-pos.x)**2+(a.p[2]-pos.z)**2)-((b.p[0]-pos.x)**2+(b.p[2]-pos.z)**2)).slice(0,8);const assigned=new Set();for(const slot of slots){if(near.includes(slot.target)){assigned.add(slot.target);}else slot.target=null;}for(const slot of slots)if(!slot.target){slot.target=near.find(h=>!assigned.has(h))||null;if(slot.target)assigned.add(slot.target);}}};
}
